#!/usr/bin/env python3
"""Generate Swift and C++ constants from frozen #0010 model/profile JSON (repr() keeps exact doubles)."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

HEADER = ("Generated by tools/key-model/export_weights.py from {model} (SHA-256 {mh}) and {prof} (SHA-256 {ph}).\n"
          "Weights derive from CC BY-SA 4.0 annotations: GiantSteps+ v2 (Zenodo 4153506) and GiantSteps-MTG\n"
          "(Zenodo 1101082, Eduard Mas Marin and Angel Faraldo), plus trusted IFEELVOID catalog labels. Do not edit.")


def flat(values) -> list[float]:
    return [v for row in values for v in (row if isinstance(row, list) else [row])]


def swift_array(name: str, values: list[float]) -> str:
    body = ",\n        ".join(", ".join(repr(v) for v in values[i:i + 6]) for i in range(0, len(values), 6))
    return f"    static let {name}: [Double] = [\n        {body}\n    ]\n"


def cpp_array(name: str, values: list[float]) -> str:
    body = ",\n    ".join(", ".join(repr(v) for v in values[i:i + 6]) for i in range(0, len(values), 6))
    return f"inline constexpr double {name}[{len(values)}] = {{\n    {body}\n}};\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--model", type=Path, required=True)
    parser.add_argument("--profiles", type=Path, required=True)
    parser.add_argument("--swift", type=Path, required=True)
    parser.add_argument("--cpp", type=Path, required=True)
    args = parser.parse_args()
    model = json.loads(args.model.read_text())
    profiles = json.loads(args.profiles.read_text())
    w = model["weights"]
    arrays = {"hiddenWeights": flat(w["0.weight"]), "hiddenBias": w["0.bias"],
              "outputWeights": flat(w["3.weight"]), "outputBias": w["3.bias"],
              "trapMajorProfile": profiles["majorProfile"], "trapMinorProfile": profiles["minorProfile"]}
    note = HEADER.format(model=args.model.name, mh=hashlib.sha256(args.model.read_bytes()).hexdigest(),
                         prof=args.profiles.name, ph=hashlib.sha256(args.profiles.read_bytes()).hexdigest())
    swift = "// " + note.replace("\n", "\n// ") + "\n\nenum KeyModelWeights {\n"
    swift += f"    static let hiddenUnits = {len(w['0.bias'])}\n"
    swift += "".join(swift_array(k, v) for k, v in arrays.items()) + "}\n"
    cpp = "// " + note.replace("\n", "\n// ") + "\n#pragma once\n\nnamespace KeyModelWeights {\n"
    cpp += f"inline constexpr int hiddenUnits = {len(w['0.bias'])};\n"
    cpp += "".join(cpp_array(k, v) for k, v in arrays.items()) + "}\n"
    args.swift.write_text(swift)
    args.cpp.write_text(cpp)


if __name__ == "__main__":
    main()
